  CREATE ROLE izo_montaj_writer NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  GRANT izo_montaj_writer TO postgres WITH INHERIT FALSE, SET TRUE;
  GRANT USAGE ON SCHEMA public TO izo_montaj_writer;
  CREATE TABLE public.izo_tronson_config (
    tronson_id bigint PRIMARY KEY REFERENCES public.executie_tronsoane(id) ON DELETE RESTRICT,
    proiect_id bigint NOT NULL REFERENCES public.executie_proiecte(id) ON DELETE RESTRICT,
    flux_montaj boolean NOT NULL DEFAULT false, flux_de_la timestamptz,
    flux_motiv text, flux_schimbat_de text,
    sens_numerotare text NOT NULL DEFAULT 'crescator' CHECK (sens_numerotare IN ('crescator','descrescator')),
    nr_sudura_start integer CHECK (nr_sudura_start > 0),
    perete_proiectat jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(perete_proiectat)='array'),
    executant_implicit text NOT NULL DEFAULT 'Gazpet',
    server_ver bigint NOT NULL DEFAULT nextval('public.izo_server_ver_seq'),
    CHECK (sens_numerotare <> 'descrescator' OR nr_sudura_start IS NOT NULL)
  );
  ALTER TABLE public.izo_tronson_config ENABLE ROW LEVEL SECURITY;
  REVOKE ALL ON public.izo_tronson_config FROM PUBLIC,anon,authenticated,service_role;
  GRANT SELECT ON public.izo_tronson_config TO authenticated,izo_montaj_writer;
  GRANT UPDATE(flux_montaj,flux_de_la,flux_motiv,flux_schimbat_de,server_ver) ON public.izo_tronson_config TO izo_montaj_writer;
  GRANT USAGE ON SEQUENCE public.izo_server_ver_seq TO izo_montaj_writer;
  CREATE POLICY izo_tronson_config_api_sel ON public.izo_tronson_config FOR SELECT TO authenticated
    USING (auth.uid() IS NOT NULL AND public.fn_izo_citire(proiect_id));
  CREATE POLICY izo_montaj_config_sel ON public.izo_tronson_config FOR SELECT TO izo_montaj_writer USING (proiect_id IS NOT NULL);
  CREATE POLICY izo_montaj_config_upd ON public.izo_tronson_config FOR UPDATE TO izo_montaj_writer
    USING (proiect_id IS NOT NULL) WITH CHECK (proiect_id IS NOT NULL);

  -- E4a has no API writer yet (Q-E4-9). Administrative entries only, session postgres.
  CREATE FUNCTION public.fn_izo_flux_config_garda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  BEGIN
    IF session_user <> 'postgres' THEN RAISE EXCEPTION 'E4a config administrativa' USING ERRCODE='42501'; END IF;
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'E4a config nu se sterge'; END IF;
    IF NEW.proiect_id IS DISTINCT FROM (SELECT proiect_id FROM public.executie_tronsoane WHERE id=NEW.tronson_id)
      THEN RAISE EXCEPTION 'E4a proiect tronson diferit'; END IF;
    IF TG_OP='INSERT' AND NEW.flux_montaj THEN RAISE EXCEPTION 'E4a activare numai prin fn_izo_seteaza_flux'; END IF;
    IF TG_OP='UPDATE' AND (NEW.tronson_id,NEW.proiect_id) IS DISTINCT FROM (OLD.tronson_id,OLD.proiect_id)
      THEN RAISE EXCEPTION 'E4a identitate config fixa'; END IF;
    IF TG_OP='UPDATE' AND NEW.flux_montaj IS DISTINCT FROM OLD.flux_montaj
      AND current_setting('izo.montaj_ctx',true) IS DISTINCT FROM txid_current()::text || '|flux|' || NEW.tronson_id
      THEN RAISE EXCEPTION 'E4a activare numai prin functie'; END IF;
    RETURN NEW;
  END $f$;
  CREATE TRIGGER a0_izo_flux_config BEFORE INSERT OR UPDATE OR DELETE ON public.izo_tronson_config
    FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_config_garda();
  ALTER TABLE public.izo_tronson_config ENABLE ALWAYS TRIGGER a0_izo_flux_config;

  -- No row locks: fast refusal first; shared project advisory + reread otherwise (§7.4).
  CREATE FUNCTION public.fn_izo_flux_garda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_old jsonb; v_new jsonb; v_tr bigint[]; v_pr bigint[]; v_flux boolean; v_pass integer;
  BEGIN
    IF TG_OP<>'INSERT' THEN v_old:=to_jsonb(OLD); END IF;
    IF TG_OP<>'DELETE' THEN v_new:=to_jsonb(NEW); END IF;
    -- INSERT keeps the legacy lock order; AFTER validates the final header after
    -- defaults/numbering and the legacy shared advisory lock (including km).
    IF TG_TABLE_NAME='executie_pachete_lansare' AND TG_OP='INSERT' THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME IN ('executie_tevi','executie_pachete_documente') THEN
      SELECT array_agg(p.tronson_id),array_agg(p.proiect_id) INTO v_tr,v_pr FROM public.executie_pachete_lansare p
        WHERE p.id IN ((v_old->>'pachet_id')::bigint,(v_new->>'pachet_id')::bigint);
    ELSIF TG_TABLE_NAME='executie_tronsoane' THEN
      v_tr:=ARRAY[(v_old->>'id')::bigint,(v_new->>'id')::bigint];
      v_pr:=ARRAY[(v_old->>'proiect_id')::bigint,(v_new->>'proiect_id')::bigint];
    ELSE
      v_tr:=ARRAY[(v_old->>'tronson_id')::bigint,(v_new->>'tronson_id')::bigint];
      v_pr:=ARRAY[(v_old->>'proiect_id')::bigint,(v_new->>'proiect_id')::bigint];
    END IF;
    FOR v_pass IN 1..2 LOOP
      SELECT EXISTS(SELECT 1 FROM public.izo_tronson_config c WHERE c.tronson_id=ANY(v_tr) AND c.flux_montaj) INTO v_flux;
      IF v_flux THEN
        -- The private INVOKER writer sets exact row images. No API setter is exposed.
        IF split_part(current_setting('izo.montaj_ctx',true),'|',1)=txid_current()::text
          AND split_part(current_setting('izo.montaj_ctx',true),'|',2) IN ('leaga','dezleaga')
          AND split_part(current_setting('izo.montaj_ctx',true),'|',3)=coalesce(v_new->>'pachet_id',v_new->>'id') THEN
          IF TG_TABLE_NAME='executie_tevi' AND TG_OP='UPDATE' AND
            ((nullif(current_setting('izo.montaj_rand_asteptat',true),'')::jsonb-ARRAY['poz_in_pachet','poz_km_m'])=
               (v_new-ARRAY['poz_in_pachet','poz_km_m']) OR
             (v_old-ARRAY['poz_in_pachet','poz_km_m','updated_at'])=(v_new-ARRAY['poz_in_pachet','poz_km_m','updated_at'])) THEN RETURN NEW; END IF;
          IF TG_TABLE_NAME='executie_pachete_lansare' AND TG_OP='UPDATE' AND
            (v_old-ARRAY['updated_at','nr_tevi','total_lungime_m','nr_pending_sant'])=
            (v_new-ARRAY['updated_at','nr_tevi','total_lungime_m','nr_pending_sant']) THEN RETURN NEW; END IF;
        END IF;
        -- E4a administrative server write: exact expected row, bound to transaction/package.
        -- API callers cannot impersonate session_user postgres, even with forged GUCs.
        IF TG_TABLE_NAME='executie_tevi' AND TG_OP<>'DELETE' AND session_user='postgres'
          AND current_setting('izo.montaj_ctx',true)=txid_current()::text || '|completeaza|' || (v_new->>'pachet_id')
          AND nullif(current_setting('izo.montaj_rand_asteptat',true),'')::jsonb = v_new THEN RETURN NEW; END IF;
        -- Until E4b, completeaza refuses; leaga/dezleaga use the private marker above.
        -- Minimal Transgaz entry writes exactly document + approval header, in its transaction.
        IF session_user='postgres' AND current_setting('izo.montaj_ctx',true) =
          txid_current()::text || '|transgaz|' || coalesce(v_new->>'pachet_id',v_new->>'id')
          AND ((TG_TABLE_NAME='executie_pachete_documente' AND TG_OP='INSERT')
            OR (TG_TABLE_NAME='executie_pachete_lansare' AND TG_OP='UPDATE'
              AND (v_old-ARRAY['status','aprobat_la','pdf_aprobare_path','pdf_aprobare_nume','updated_at']) =
                  (v_new-ARRAY['status','aprobat_la','pdf_aprobare_path','pdf_aprobare_nume','updated_at']))) THEN RETURN NEW; END IF;
        IF TG_TABLE_NAME='executie_pachete_documente' AND TG_OP='INSERT'
          AND v_new->>'tip_document' IS DISTINCT FROM 'pdf_aprobare_transgaz' THEN RETURN NEW; END IF;
        -- Only ordinary header metadata may be edited by the client. All other
        -- columns, including new columns added later, remain protected.
        IF TG_TABLE_NAME='executie_pachete_lansare' AND TG_OP='UPDATE'
          AND (v_old-ARRAY['observatii','data_lansare','updated_at']) =
              (v_new-ARRAY['observatii','data_lansare','updated_at']) THEN
          -- A caller must not rewind the header CAS after a structural write.
          NEW.updated_at:=clock_timestamp();
          RETURN NEW;
        END IF;
        IF TG_TABLE_NAME='executie_pachete_lansare' AND TG_OP='UPDATE'
          AND (v_old-ARRAY['updated_at','nr_tevi','total_lungime_m','nr_pending_sant']) =
              (v_new-ARRAY['updated_at','nr_tevi','total_lungime_m','nr_pending_sant'])
          AND session_user='postgres' AND current_setting('izo.montaj_ctx',true) LIKE txid_current()::text || '|transgaz|%'
          THEN RETURN NEW; END IF;
        RAISE EXCEPTION 'E4a flux: scriere client refuzata pe %',TG_TABLE_NAME USING ERRCODE='42501';
      END IF;
      IF v_pass=1 THEN PERFORM public.fn_izo_lock_partajat(VARIADIC array_remove(v_pr,NULL)); END IF;
    END LOOP;
    RETURN (CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END);
  END $f$;
  CREATE FUNCTION public.fn_izo_flux_pachet_dupa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_j jsonb:=to_jsonb(NEW);
  BEGIN
    IF EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=NEW.tronson_id AND flux_montaj)
      AND (v_j->>'status' IS DISTINCT FROM 'draft' OR v_j->>'km_start_m' IS NOT NULL
        OR coalesce((v_j->>'nr_tevi')::numeric,0)<>0
        OR coalesce((v_j->>'total_lungime_m')::numeric,0)<>0
        OR coalesce((v_j->>'nr_pending_sant')::numeric,0)<>0 OR EXISTS
        (SELECT 1 FROM jsonb_each(v_j) e WHERE (e.key LIKE 'aprobat_%' OR e.key LIKE 'pdf_aprobare_%') AND e.value<>'null'::jsonb))
      THEN RAISE EXCEPTION 'E4a flux: antet initial invalid din client' USING ERRCODE='42501'; END IF;
    RETURN NEW;
  END $f$;
  CREATE TRIGGER a0_izo_flux_tevi BEFORE INSERT OR UPDATE OR DELETE ON public.executie_tevi FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_garda();
  CREATE TRIGGER a0_izo_flux_pachete BEFORE INSERT OR UPDATE OR DELETE ON public.executie_pachete_lansare FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_garda();
  CREATE TRIGGER a0_izo_flux_pachete_dupa AFTER INSERT ON public.executie_pachete_lansare FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_pachet_dupa();
  CREATE TRIGGER a0_izo_flux_documente BEFORE INSERT OR UPDATE OR DELETE ON public.executie_pachete_documente FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_garda();
  CREATE TRIGGER a0_izo_flux_tronsoane BEFORE UPDATE OR DELETE ON public.executie_tronsoane FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_garda();
  ALTER TABLE public.executie_tevi ENABLE ALWAYS TRIGGER a0_izo_flux_tevi;
  ALTER TABLE public.executie_pachete_lansare ENABLE ALWAYS TRIGGER a0_izo_flux_pachete;
  ALTER TABLE public.executie_pachete_lansare ENABLE ALWAYS TRIGGER a0_izo_flux_pachete_dupa;
  ALTER TABLE public.executie_pachete_documente ENABLE ALWAYS TRIGGER a0_izo_flux_documente;
  ALTER TABLE public.executie_tronsoane ENABLE ALWAYS TRIGGER a0_izo_flux_tronsoane;

  CREATE FUNCTION public.fn_izo_flux_storage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  BEGIN
    IF EXISTS (SELECT 1 FROM public.executie_pachete_documente d JOIN public.executie_pachete_lansare p ON p.id=d.pachet_id
      JOIN public.izo_tronson_config c ON c.tronson_id=p.tronson_id AND c.flux_montaj
      WHERE d.fisier_path=OLD.name AND OLD.bucket_id='executie-pachete-pdf') THEN
      RAISE EXCEPTION 'E4a PDF flux imuabil' USING ERRCODE='42501'; END IF;
    RETURN (CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END);
  END $f$;
  CREATE TRIGGER a0_izo_flux_storage BEFORE UPDATE OR DELETE ON storage.objects FOR EACH ROW EXECUTE FUNCTION public.fn_izo_flux_storage();
  ALTER TABLE storage.objects ENABLE ALWAYS TRIGGER a0_izo_flux_storage;

  -- Administrative helper takes locks unavailable to the NOLOGIN writer; never exposed to API.
  CREATE FUNCTION public.fn_izo_flux_admin(p_tronson bigint,p_activ boolean,p_motiv text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_pr bigint; v_c public.izo_tronson_config; v_lipsa text[];
  BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'E4a READ COMMITTED' USING ERRCODE='25001'; END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
    IF session_user<>'postgres' THEN RAISE EXCEPTION 'E4a numai sesiune postgres' USING ERRCODE='42501'; END IF;
    IF coalesce(current_setting('izo.montaj_ctx',true),'')<>'' OR coalesce(current_setting('izo.receptie_ctx',true),'')<>''
      OR coalesce(current_setting('izo.registru_tx',true),'')<>'' THEN RAISE EXCEPTION 'E4a context ocupat'; END IF;
    IF p_activ IS NULL OR length(btrim(coalesce(p_motiv,'')))<3 THEN RAISE EXCEPTION 'E4a parametri flux'; END IF;
    IF p_activ THEN
      v_lipsa:=public.fn_izo_porti_lipsa();
      IF cardinality(v_lipsa)<>0 THEN RAISE EXCEPTION 'E4a porti: %',v_lipsa; END IF;
    END IF;
    LOCK TABLE public.izo_tronson_config,public.executie_tronsoane,public.executie_pachete_lansare,
      public.executie_tevi,public.magazie_bucati,public.magazie_bucati_evenimente IN ACCESS SHARE MODE;
    SELECT proiect_id INTO v_pr FROM public.executie_tronsoane WHERE id=p_tronson;
    IF v_pr IS NULL THEN RAISE EXCEPTION 'E4a tronson lipsa'; END IF;
    PERFORM public.fn_izo_lock_proiect(v_pr,true);
    SELECT * INTO v_c FROM public.izo_tronson_config WHERE tronson_id=p_tronson FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'config_lipsa'; END IF;
    IF v_c.proiect_id<>v_pr THEN RAISE EXCEPTION 'E4a proiect diferit'; END IF;
    IF p_activ THEN
      IF coalesce(public.fn_izo_nivel(v_pr),'off')='off' THEN RAISE EXCEPTION 'E4a nivel off'; END IF;
      -- E4a-1 cannot verify a legare without E4b suduri: fail closed on that row type.
      IF EXISTS(SELECT 1 FROM public.executie_tevi t JOIN public.executie_pachete_lansare p ON p.id=t.pachet_id
        WHERE p.tronson_id=p_tronson AND (coalesce(to_jsonb(t)->>'tip_rand','teava') NOT IN ('teava','curba')
          OR (SELECT count(*) FROM public.magazie_bucati b WHERE b.executie_teava_id=t.id AND b.stare='montata'
            AND b.tronson_id=p_tronson AND b.proiect_id=v_pr
            AND b.tip_cod=coalesce(to_jsonb(t)->>'tip_rand','teava'))<>1))
        THEN RAISE EXCEPTION 'E4a randuri nelegate'; END IF;
      IF EXISTS(SELECT 1 FROM public.executie_pachete_lansare p WHERE p.tronson_id=p_tronson
        AND (to_jsonb(p)->>'aprobat_la' IS NOT NULL OR to_jsonb(p)->>'pdf_aprobare_path' IS NOT NULL
          OR to_jsonb(p)->>'status' IN ('aprobat','lansat','finalizat'))) THEN RAISE EXCEPTION 'E4a antet aprobat'; END IF;
    ELSE
      IF EXISTS(SELECT 1 FROM public.magazie_bucati WHERE tronson_id=p_tronson AND stare IN ('montata','taiata'))
        OR EXISTS(SELECT 1 FROM public.magazie_bucati_miscari m JOIN public.magazie_bucati_evenimente e ON e.id=m.eveniment_id
          WHERE e.proiect_id=v_pr AND e.tip IN ('montaj','taiere') AND
            (m.inainte->>'tronson_id'=p_tronson::text OR m.dupa->>'tronson_id'=p_tronson::text
             OR m.din_loc->>'tronson_id'=p_tronson::text OR m.in_loc->>'tronson_id'=p_tronson::text))
        THEN RAISE EXCEPTION 'E4a fapte montaj; oprire refuzata'; END IF;
      -- Later E4b must replace this entry with checks on declarations/reservations/fronts.
      IF to_regclass('public.izo_declaratii') IS NOT NULL OR to_regclass('public.izo_rezervari') IS NOT NULL
        OR to_regclass('public.izo_fronturi') IS NOT NULL THEN RAISE EXCEPTION 'E4a oprirea necesita garda E4b'; END IF;
    END IF;
    PERFORM set_config('izo.montaj_ctx',txid_current()::text || '|flux|' || p_tronson,true);
    UPDATE public.izo_tronson_config SET flux_montaj=p_activ,flux_de_la=clock_timestamp(),flux_motiv=btrim(p_motiv),
      flux_schimbat_de=session_user,server_ver=nextval('public.izo_server_ver_seq') WHERE tronson_id=p_tronson;
    PERFORM set_config('izo.montaj_ctx','',true);
    RETURN p_activ;
  END $f$;
  CREATE FUNCTION public.fn_izo_seteaza_flux(p_tronson bigint,p_activ boolean,p_motiv text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
    SELECT public.fn_izo_flux_admin(p_tronson,p_activ,p_motiv)
  $f$;

  -- Minimal administrative approval, no API grant until module authorization is approved.
  CREATE FUNCTION public.fn_izo_flux_aprobare_admin(p_pachet bigint,p_updated_at timestamptz,p_nume text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_p public.executie_pachete_lansare; v_path text; v_pr bigint; v_tr bigint; v_lipsa text[];
  BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'E4a READ COMMITTED' USING ERRCODE='25001'; END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
    IF session_user<>'postgres' THEN RAISE EXCEPTION 'E4a numai postgres' USING ERRCODE='42501'; END IF;
    IF coalesce(current_setting('izo.montaj_ctx',true),'')<>'' THEN RAISE EXCEPTION 'E4a context ocupat'; END IF;
    v_lipsa:=public.fn_izo_porti_lipsa(); IF cardinality(v_lipsa)<>0 THEN RAISE EXCEPTION 'E4a porti %',v_lipsa; END IF;
    SELECT proiect_id,tronson_id INTO v_pr,v_tr FROM public.executie_pachete_lansare WHERE id=p_pachet;
    PERFORM public.fn_izo_blocheaza_locuri(v_pr,ARRAY[]::integer[],ARRAY[v_tr]);
    SELECT * INTO v_p FROM public.executie_pachete_lansare WHERE id=p_pachet FOR NO KEY UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'pachet_lipsa'; END IF;
    PERFORM 1 FROM public.executie_tevi WHERE pachet_id=p_pachet ORDER BY id FOR NO KEY UPDATE;
    PERFORM public.fn_izo_blocheaza_tabele(); PERFORM public.fn_izo_lock_partajat(v_pr);
    IF v_p.proiect_id IS DISTINCT FROM v_pr OR v_p.tronson_id IS DISTINCT FROM v_tr
      OR v_pr IS DISTINCT FROM (SELECT proiect_id FROM public.executie_tronsoane WHERE id=v_tr) THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND flux_montaj) THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
    IF (to_jsonb(v_p)->>'updated_at')::timestamptz IS DISTINCT FROM p_updated_at OR p_updated_at IS NULL THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    IF to_jsonb(v_p)->>'status' IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'pachet_needitabil'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.executie_tevi WHERE pachet_id=p_pachet) THEN RAISE EXCEPTION 'pachet_gol'; END IF;
    -- Minimal variant: only existing teava/curba links can be proven before E4b.
    -- legare needs E4b's coupling verifier; refuse rather than approve incomplete evidence.
    PERFORM 1 FROM public.magazie_bucati b WHERE b.executie_teava_id IN
      (SELECT id FROM public.executie_tevi WHERE pachet_id=p_pachet) ORDER BY b.id FOR SHARE;
    IF EXISTS(SELECT 1 FROM public.executie_tevi t WHERE t.pachet_id=p_pachet AND
      (coalesce(to_jsonb(t)->>'tip_rand','teava') NOT IN ('teava','curba') OR
       (SELECT count(*) FROM public.magazie_bucati b WHERE b.executie_teava_id=t.id AND b.stare='montata'
         AND b.proiect_id=v_pr AND b.tronson_id=v_tr AND b.tip_cod=coalesce(to_jsonb(t)->>'tip_rand','teava')
         AND to_jsonb(t) @> public.fn_izo_flux_pachet_identitate(b))<>1))
      THEN RAISE EXCEPTION 'rand_nelegat_sau_proiectie_invalida'; END IF;
    IF p_nume IS NULL OR p_nume !~ '^[^/\\]+[.]pdf$' THEN RAISE EXCEPTION 'nume_pdf_invalid'; END IF;
    v_path:=v_pr::text || '/' || p_pachet::text || '/aprobare/' || md5(extract(epoch FROM p_updated_at)::text) || '.pdf';
    -- Storage must already contain the signed PDF at this server supplied path.
    -- First call returns a deterministic server path; retry after upload revalidates CAS.
    IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='executie-pachete-pdf' AND name=v_path) THEN
      RETURN jsonb_build_object('cod','incarca_pdf','fisier_path',v_path,'pachet_updated_at',p_updated_at); END IF;
    PERFORM set_config('izo.montaj_ctx',txid_current()::text || '|transgaz|' || p_pachet,true);
    INSERT INTO public.executie_pachete_documente(pachet_id,tip_document,fisier_path,fisier_nume,mime_type)
      VALUES(p_pachet,'pdf_aprobare_transgaz',v_path,p_nume,'application/pdf');
    UPDATE public.executie_pachete_lansare SET status='aprobat',aprobat_la=clock_timestamp(),pdf_aprobare_path=v_path,
      pdf_aprobare_nume=p_nume,updated_at=clock_timestamp() WHERE id=p_pachet;
    PERFORM set_config('izo.montaj_ctx','',true);
    RETURN jsonb_build_object('cod','aprobat','fisier_path',v_path);
  END $f$;
  CREATE FUNCTION public.fn_izo_pachet_aprobare_transgaz(p_pachet bigint,p_updated_at timestamptz,p_nume text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
    SELECT public.fn_izo_flux_aprobare_admin(p_pachet,p_updated_at,p_nume)
  $f$;
  REVOKE ALL ON FUNCTION public.fn_izo_flux_config_garda(),public.fn_izo_flux_garda(),public.fn_izo_flux_pachet_dupa(),
    public.fn_izo_flux_storage(),public.fn_izo_flux_admin(bigint,boolean,text),public.fn_izo_seteaza_flux(bigint,boolean,text),
    public.fn_izo_flux_aprobare_admin(bigint,timestamptz,text),public.fn_izo_pachet_aprobare_transgaz(bigint,timestamptz,text) FROM PUBLIC,anon,authenticated,service_role;
  GRANT EXECUTE ON FUNCTION public.fn_izo_flux_admin(bigint,boolean,text),public.fn_izo_flux_aprobare_admin(bigint,timestamptz,text) TO izo_montaj_writer;
  GRANT CREATE ON SCHEMA public TO izo_montaj_writer;
  ALTER FUNCTION public.fn_izo_seteaza_flux(bigint,boolean,text) OWNER TO izo_montaj_writer;
  ALTER FUNCTION public.fn_izo_pachet_aprobare_transgaz(bigint,timestamptz,text) OWNER TO izo_montaj_writer;
  REVOKE CREATE ON SCHEMA public FROM izo_montaj_writer;
  SET LOCAL ROLE izo_montaj_writer;
  GRANT EXECUTE ON FUNCTION public.fn_izo_seteaza_flux(bigint,boolean,text),public.fn_izo_pachet_aprobare_transgaz(bigint,timestamptz,text) TO postgres;
  RESET ROLE;

    -- E4a-2b: private marker; never grant this entry to API roles.
  CREATE FUNCTION public.fn_izo_montaj_marcheaza(p_ctx text,p_inainte jsonb,p_dupa jsonb,p_rand jsonb)
    RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  BEGIN
    IF current_user <> 'izo_montaj_writer' THEN
      RAISE EXCEPTION 'E4a marcaj: scriitor invalid' USING ERRCODE='42501'; END IF;
    PERFORM set_config('izo.montaj_ctx',coalesce(p_ctx,''),true);
    PERFORM set_config('izo.montaj_bucata_inainte',coalesce(p_inainte::text,''),true);
    PERFORM set_config('izo.montaj_bucata_dupa',coalesce(p_dupa::text,''),true);
    PERFORM set_config('izo.montaj_rand_asteptat',coalesce(p_rand::text,''),true);
  END $f$;

  CREATE FUNCTION public.fn_izo_garda_montaj(p_tabel text,p_op text,p_inainte jsonb,p_dupa jsonb)
    RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE v_ctx text:=current_setting('izo.montaj_ctx',true); v_pachet bigint; v_op text; v_dupa_comparabil jsonb;
  BEGIN
    -- E4a writes only the link. No events/movements/imports/config authorization yet.
    IF current_user='izo_montaj_writer' AND p_tabel='magazie_bucati' AND p_op='UPDATE'
      AND p_inainte IS NOT NULL AND p_dupa IS NOT NULL
      -- PG16 computes STORED generated columns AFTER BEFORE triggers: NEW has NULL.
      -- Require that exact trigger shape; restore only these two derived values for
      -- comparison with the stored snapshot. Their sources (serie/lungime_mm) stay immutable.
      AND p_dupa->'serie_canon' = 'null'::jsonb AND p_dupa->'lungime_cm' = 'null'::jsonb THEN
      v_dupa_comparabil:=p_dupa || jsonb_build_object(
        'serie_canon',p_inainte->'serie_canon','lungime_cm',p_inainte->'lungime_cm');
      v_op:=CASE WHEN p_dupa->>'executie_teava_id' IS NULL THEN 'dezleaga' ELSE 'leaga' END;
      SELECT pachet_id INTO v_pachet FROM public.executie_tevi
        WHERE id=coalesce((p_dupa->>'executie_teava_id')::bigint,(p_inainte->>'executie_teava_id')::bigint);
      IF v_ctx = concat_ws('|',txid_current()::text,v_op,v_pachet::text,
          p_inainte->>'proiect_id',p_inainte->>'tronson_id',p_dupa->>'server_ver',p_inainte->>'id')
        AND v_pachet IS NOT NULL AND p_inainte->>'tip_cod' IN ('teava','curba')
        AND p_inainte->>'stare'='montata'
        AND ((v_op='leaga' AND p_inainte->>'executie_teava_id' IS NULL)
          OR (v_op='dezleaga' AND p_inainte->>'executie_teava_id' IS NOT NULL))
        AND nullif(current_setting('izo.montaj_bucata_inainte',true),'')::jsonb=p_inainte
        AND nullif(current_setting('izo.montaj_bucata_dupa',true),'')::jsonb=v_dupa_comparabil
        AND (p_inainte-ARRAY['executie_teava_id','server_ver','updated_at'])=
            (v_dupa_comparabil-ARRAY['executie_teava_id','server_ver','updated_at']) THEN RETURN true; END IF;
    END IF;
    RAISE EXCEPTION 'E4a context montaj invalid pe %',p_tabel USING ERRCODE='42501';
  END $f$;
  REVOKE ALL ON FUNCTION public.fn_izo_montaj_marcheaza(text,jsonb,jsonb,jsonb),
    public.fn_izo_garda_montaj(text,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
  GRANT EXECUTE ON FUNCTION public.fn_izo_garda_montaj(text,text,jsonb,jsonb) TO izo_montaj_writer;
  GRANT CREATE ON SCHEMA public TO izo_montaj_writer;
  ALTER FUNCTION public.fn_izo_montaj_marcheaza(text,jsonb,jsonb,jsonb) OWNER TO izo_montaj_writer;
  REVOKE CREATE ON SCHEMA public FROM izo_montaj_writer;

    CREATE OR REPLACE FUNCTION public.fn_izo_garda_bucati() RETURNS trigger
    LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE
    v_old boolean := false;
    v_new boolean := false;
    v_p bigint;
    v_aut boolean;
  BEGIN
    -- E3 (20261103b): predicatul de autorizare, calculat o singură dată — scriitorul E2a cu marcaj SAU scriitorul E3 în
    -- contextul operației (true sau excepție); fără RETURN timpuriu: verificările E2a de mai jos se aplică tuturor
    v_aut := public.fn_izo_garda_scriitor();
    IF v_aut IS NOT TRUE AND current_user = 'izo_montaj_writer' THEN
      v_aut := public.fn_izo_garda_montaj(TG_TABLE_NAME, TG_OP,
        CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
        CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END);
    END IF;
    IF v_aut IS NOT TRUE AND current_user = 'izo_receptie_writer' THEN
      v_aut := public.fn_izo_garda_receptie(TG_TABLE_NAME, TG_OP, CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
                                            CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END);
    END IF;
    IF v_aut IS NOT TRUE AND current_user = 'izo_corectie_writer' THEN
      v_aut := public.fn_izo_garda_corectie(TG_TABLE_NAME, TG_OP,
        CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END, CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END);
    END IF;
    -- (1) rândurile registrului sunt protejate PERMANENT: refuz imediat, fără lock (altfel un UPDATE al clientului, care
    --     ține deja rândul, ar aștepta lock-ul advisory al unui storno care așteaptă rândul → blocaj circular)
    IF ((TG_OP <> 'INSERT' AND OLD.tip_cod IS NOT NULL) OR (TG_OP <> 'DELETE' AND NEW.tip_cod IS NOT NULL))
       AND v_aut IS NOT TRUE THEN
      RAISE EXCEPTION 'izo: bucățile beneficiar ale unui proiect cu registru (nivel ≠ off) se scriu doar prin funcțiile registrului'
        USING ERRCODE = '42501';
    END IF;
    -- (2) beneficiar în afara registrului: lock PARTAJAT pe proiectele OLD/NEW (crescător; cere READ COMMITTED — sub
    --     REPEATABLE READ o activare comisă între timp n-ar fi văzută), apoi nivelul, citit cu snapshot nou
    IF (TG_OP <> 'INSERT' AND OLD.provenienta = 'beneficiar') OR (TG_OP <> 'DELETE' AND NEW.provenienta = 'beneficiar') THEN
      IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'izo: scrierile care ating registrul cer READ COMMITTED (acum %)', current_setting('transaction_isolation')
          USING ERRCODE = '25001';
      END IF;
      FOR v_p IN SELECT DISTINCT x FROM unnest(ARRAY[CASE WHEN TG_OP <> 'INSERT' AND OLD.provenienta = 'beneficiar' THEN OLD.proiect_id END,
                                                       CASE WHEN TG_OP <> 'DELETE' AND NEW.provenienta = 'beneficiar' THEN NEW.proiect_id END]) x
                  WHERE x IS NOT NULL ORDER BY 1 LOOP
        PERFORM pg_advisory_xact_lock_shared(73010, v_p::integer);
      END LOOP;
    END IF;
    IF TG_OP <> 'INSERT' AND (OLD.tip_cod IS NOT NULL OR OLD.provenienta = 'beneficiar') THEN
      v_old := OLD.tip_cod IS NOT NULL OR public.fn_izo_nivel(OLD.proiect_id) <> 'off';
    END IF;
    IF TG_OP <> 'DELETE' AND (NEW.tip_cod IS NOT NULL OR NEW.provenienta = 'beneficiar') THEN
      v_new := NEW.tip_cod IS NOT NULL OR public.fn_izo_nivel(NEW.proiect_id) <> 'off';
    END IF;
    IF v_old OR v_new THEN
      IF v_aut IS NOT TRUE THEN
        RAISE EXCEPTION 'izo: bucățile beneficiar ale unui proiect cu registru (nivel ≠ off) se scriu doar prin funcțiile registrului'
          USING ERRCODE = '42501';
      END IF;
      IF TG_OP <> 'DELETE' AND NEW.stare IN ('rezervata','consumata') THEN
        RAISE EXCEPTION 'izo: starea % e interzisă pe bucățile registrului (rezervările stau în izo_rezervari; consumul = montata/taiata)', NEW.stare
          USING ERRCODE = '23514';
      END IF;
      IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'izo: bucățile registrului nu se șterg (anulare = storno)' USING ERRCODE = '42501';
      END IF;
      -- un rând de registru nu stă niciodată pe un proiect off (nici scris de writer) — review #806 A
      IF TG_OP <> 'DELETE' AND NEW.tip_cod IS NOT NULL AND public.fn_izo_nivel(NEW.proiect_id) = 'off' THEN
        RAISE EXCEPTION 'izo: rândurile registrului cer proiect cu nivel ≠ off (proiectul %)', NEW.proiect_id USING ERRCODE = '42501';
      END IF;
    END IF;
    -- tip_cod e copie controlată de server: trebuie să bată cu tip_material_id
    IF TG_OP <> 'DELETE' AND NEW.tip_cod IS NOT NULL AND NEW.tip_cod IS DISTINCT FROM public.fn_izo_tip_cod(NEW.tip_material_id) THEN
      RAISE EXCEPTION 'izo: tip_cod % nu bate cu tip_material_id %', NEW.tip_cod, NEW.tip_material_id USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END $f$;
    CREATE OR REPLACE FUNCTION public.fn_izo_garda_fapte() RETURNS trigger
    LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE v_aut boolean;
  BEGIN
    IF TG_OP = 'TRUNCATE' THEN
      RAISE EXCEPTION 'izo: TRUNCATE pe % e refuzat (registru doar-adaug)', TG_TABLE_NAME USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'izo: DELETE pe % e refuzat (registru doar-adaug; anulare = storno)', TG_TABLE_NAME USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'UPDATE' AND TG_TABLE_NAME IN ('magazie_bucati_evenimente','magazie_bucati_miscari') THEN
      RAISE EXCEPTION 'izo: UPDATE pe % e refuzat (registru doar-adaug)', TG_TABLE_NAME USING ERRCODE = '42501';
    END IF;
    -- E3 (20261103b): predicatul de autorizare, calculat o singură dată — scriitorul E2a cu marcaj SAU scriitorul E3 în
    -- contextul operației (true sau excepție); fără RETURN timpuriu: verificările E2a de mai jos se aplică tuturor
    v_aut := public.fn_izo_garda_scriitor();
    IF v_aut IS NOT TRUE AND current_user = 'izo_montaj_writer' THEN
      v_aut := public.fn_izo_garda_montaj(TG_TABLE_NAME, TG_OP,
        CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
        CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END);
    END IF;
    IF v_aut IS NOT TRUE AND current_user = 'izo_receptie_writer' THEN
      v_aut := public.fn_izo_garda_receptie(TG_TABLE_NAME, TG_OP, CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
                                            to_jsonb(NEW));
    END IF;
    IF v_aut IS NOT TRUE AND current_user = 'izo_corectie_writer' THEN
      v_aut := public.fn_izo_garda_corectie(TG_TABLE_NAME, TG_OP,
        CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END, CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END);
    END IF;
    IF v_aut IS NOT TRUE THEN
      RAISE EXCEPTION 'izo: % se scrie doar prin funcțiile registrului', TG_TABLE_NAME USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END $f$;
    -- E4a-2. API wrappers contain no context setter; internal entries are not executable by API roles.
  IF EXISTS(SELECT 1 FROM public.magazie_bucati WHERE tip_cod IS NOT NULL AND executie_teava_id IS NOT NULL) THEN
    RAISE EXCEPTION 'E4a preflight: bucati deja legate'; END IF;
  CREATE UNIQUE INDEX ux_magbuc_izo_teava ON public.magazie_bucati(executie_teava_id)
    WHERE executie_teava_id IS NOT NULL AND tip_cod IS NOT NULL AND stare <> 'anulata';

  CREATE FUNCTION public.fn_izo_flux_pachet_lock(p_teava bigint,p_pachet bigint,p_updated_at timestamptz)
    RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_p public.executie_pachete_lansare; v_t public.executie_tevi; v_id bigint;
    v_pr bigint; v_tr bigint; v_owner boolean; v_uid uuid; v_lipsa text[];
  BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'E4a READ COMMITTED' USING ERRCODE='25001'; END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
    IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' THEN
      RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
    v_uid:=public.fn_izo_uid();
    IF coalesce(current_setting('izo.montaj_ctx',true),'')<>''
      OR coalesce(current_setting('izo.receptie_ctx',true),'')<>''
      OR coalesce(current_setting('izo.registru_tx',true),'')<>'' THEN RAISE EXCEPTION 'context_ocupat'; END IF;
    v_id:=p_pachet;
    IF p_teava IS NOT NULL THEN SELECT pachet_id INTO v_id FROM public.executie_tevi WHERE id=p_teava; END IF;
    SELECT proiect_id,tronson_id INTO v_pr,v_tr FROM public.executie_pachete_lansare WHERE id=v_id;
    IF v_pr IS NULL THEN RAISE EXCEPTION 'pachet_lipsa'; END IF;
    -- Early refusal avoids the legacy row -> package lock order on non-flow tronsoane.
    IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND flux_montaj) THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
    SELECT is_owner INTO v_owner FROM public.profiles WHERE id=v_uid AND employee_id IS NOT NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
    IF v_owner IS NOT TRUE THEN
      PERFORM 1 FROM public.user_module_access WHERE profile_id=v_uid AND module='executie.izometrie'
        AND access_level IN ('editor','admin') FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
      PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=v_pr AND activ
        AND rol IN ('manager_aprobator','inlocuitor_aprobator') AND depozit_id IS NULL
        AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date) ORDER BY id FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
    END IF;
    v_lipsa:=public.fn_izo_porti_lipsa();
    IF cardinality(v_lipsa)<>0 THEN RAISE EXCEPTION 'E4a porti %',v_lipsa; END IF;
    PERFORM public.fn_izo_blocheaza_locuri(v_pr,ARRAY[]::integer[],ARRAY[v_tr]);
    SELECT * INTO v_p FROM public.executie_pachete_lansare WHERE id=v_id FOR NO KEY UPDATE;
    PERFORM 1 FROM public.executie_tronsoane WHERE id=v_tr FOR SHARE;
    -- All package rows, including rows touched by renumber/km cascades, in id order.
    PERFORM 1 FROM public.executie_tevi WHERE pachet_id=v_id ORDER BY id FOR NO KEY UPDATE;
    IF p_teava IS NOT NULL THEN SELECT * INTO v_t FROM public.executie_tevi WHERE id=p_teava; END IF;
    PERFORM public.fn_izo_blocheaza_tabele();
    PERFORM public.fn_izo_lock_partajat(v_pr);
    IF v_p.proiect_id IS DISTINCT FROM v_pr OR v_p.tronson_id IS DISTINCT FROM v_tr
      OR v_pr IS DISTINCT FROM (SELECT proiect_id FROM public.executie_tronsoane WHERE id=v_tr)
      OR (p_teava IS NOT NULL AND v_t.pachet_id IS DISTINCT FROM v_id) THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    IF coalesce(public.fn_izo_nivel(v_pr),'off') NOT IN ('stoc','montaj') OR NOT EXISTS
      (SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND flux_montaj) THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
    IF p_updated_at IS NOT NULL AND p_updated_at IS DISTINCT FROM
      ((CASE WHEN p_teava IS NULL THEN to_jsonb(v_p) ELSE to_jsonb(v_t) END)->>'updated_at')::timestamptz
      THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    RETURN jsonb_build_object('pachet',to_jsonb(v_p),'teava',to_jsonb(v_t));
  END $f$;

  CREATE FUNCTION public.fn_izo_flux_pachet_editabil(p_pachet jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  BEGIN
    IF p_pachet->>'status' IS DISTINCT FROM 'draft' OR EXISTS
      (SELECT 1 FROM jsonb_each(p_pachet) e WHERE (e.key LIKE 'aprobat_%' OR e.key LIKE 'pdf_aprobare_%') AND e.value<>'null'::jsonb)
      THEN RAISE EXCEPTION 'pachet_needitabil'; END IF;
  END $f$;

  CREATE FUNCTION public.fn_izo_flux_pachet_identitate(p_b public.magazie_bucati) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE v_rad public.magazie_bucati; v_dim text;
  BEGIN
    SELECT * INTO v_rad FROM public.magazie_bucati WHERE id=coalesce(p_b.radacina_id,p_b.id);
    v_dim:=CASE WHEN p_b.diametru_mm IS NOT NULL OR p_b.perete_mm IS NOT NULL THEN
      coalesce(p_b.diametru_mm::text,'') || 'X' || coalesce(p_b.perete_mm::text,'') ||
      CASE WHEN p_b.tip_cod='curba' AND p_b.unghi_curba IS NOT NULL THEN ' ' || p_b.unghi_curba::text || '°' ELSE '' END END;
    RETURN jsonb_build_object('serie_unica',p_b.serie,'sarja',p_b.sarja,'lot',p_b.lot,
      'lungime_m',p_b.lungime_mm/1000.0,'lungime_originala_m',coalesce(v_rad.lungime_mm/1000.0,v_rad.lungime_m),
      'tip',CASE WHEN p_b.tip_cod='curba' THEN 'CIC' ELSE p_b.grad_otel END,'dimensiune',v_dim,'unghi_curba',CASE WHEN p_b.tip_cod='curba' AND p_b.unghi_curba IS NOT NULL THEN p_b.unghi_curba::text || '°' END);
  END $f$;

  CREATE FUNCTION public.fn_izo_flux_pachet_legatura(p_teava bigint,p_bucata bigint,p_updated_at timestamptz,p_motiv text,p_bucata_asteptata bigint)
    RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE v_lock jsonb; v_p jsonb; v_t public.executie_tevi; v_b public.magazie_bucati;
    v_veche bigint; v_patch jsonb; v_ctx text; v_now timestamptz:=clock_timestamp();
    v_dupa public.magazie_bucati; v_randuri bigint;
  BEGIN
    IF p_updated_at IS NULL THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    IF p_bucata IS NULL AND length(btrim(coalesce(p_motiv,'')))<3 THEN RAISE EXCEPTION 'motiv_obligatoriu'; END IF;
    -- Lock/authenticate/revalidate first; row CAS belongs below the exact replay check.
    v_lock:=public.fn_izo_flux_pachet_lock(p_teava,NULL,NULL);
    v_p:=v_lock->'pachet'; v_t:=jsonb_populate_record(NULL::public.executie_tevi,v_lock->'teava');
    IF v_t.tip_rand IS NULL OR v_t.tip_rand NOT IN ('teava','curba') THEN RAISE EXCEPTION 'rand_fara_bucata'; END IF;
    -- Natural idempotence is allowed even on an approved package; no stamp/write.
    SELECT id INTO v_veche FROM public.magazie_bucati WHERE executie_teava_id=p_teava AND tip_cod IS NOT NULL AND stare<>'anulata';
    SELECT * INTO v_b FROM public.magazie_bucati WHERE id=coalesce(p_bucata,v_veche) FOR UPDATE;
    IF p_bucata IS NOT NULL AND v_veche=p_bucata
      AND v_b.proiect_id=(v_p->>'proiect_id')::bigint AND v_b.tronson_id=(v_p->>'tronson_id')::bigint
      AND v_b.stare='montata' AND v_b.tip_cod=v_t.tip_rand
      AND to_jsonb(v_t) @> public.fn_izo_flux_pachet_identitate(v_b)
      THEN RETURN jsonb_build_object('cod','fara_efect'); END IF;
    IF v_t.updated_at IS DISTINCT FROM p_updated_at OR (p_bucata IS NULL AND
      (p_bucata_asteptata IS NULL OR v_veche IS DISTINCT FROM p_bucata_asteptata))
      THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    PERFORM public.fn_izo_flux_pachet_editabil(v_p);
    IF p_bucata IS NOT NULL AND v_veche IS NOT NULL THEN RAISE EXCEPTION 'rand_deja_legat'; END IF;
    IF v_b.id IS NULL OR v_b.proiect_id IS DISTINCT FROM (v_p->>'proiect_id')::bigint
      OR v_b.tronson_id IS DISTINCT FROM (v_p->>'tronson_id')::bigint OR v_b.stare<>'montata'
      OR v_b.tip_cod IS DISTINCT FROM v_t.tip_rand THEN RAISE EXCEPTION 'bucata_incompatibila'; END IF;
    IF p_bucata IS NOT NULL AND v_b.executie_teava_id IS NOT NULL THEN RAISE EXCEPTION 'bucata_deja_legata'; END IF;
    -- Expected stored image uses the same typed values as UPDATE.
    -- fn_izo_garda_montaj restores the two generated columns absent from BEFORE NEW.
    v_dupa:=v_b;
    v_dupa.executie_teava_id:=CASE WHEN p_bucata IS NOT NULL THEN p_teava END;
    v_dupa.server_ver:=nextval('public.izo_server_ver_seq'); v_dupa.updated_at:=v_now;
    v_ctx:=concat_ws('|',txid_current()::text,CASE WHEN p_bucata IS NULL THEN 'dezleaga' ELSE 'leaga' END,
      v_p->>'id',v_p->>'proiect_id',v_p->>'tronson_id',v_dupa.server_ver::text,v_b.id::text);
    IF p_bucata IS NOT NULL THEN
      v_patch:=public.fn_izo_flux_pachet_identitate(v_b)||jsonb_build_object('updated_at',v_now);
    ELSE
      v_patch:=jsonb_build_object('updated_at',v_now);
    END IF;
    v_t:=jsonb_populate_record(v_t,v_patch);
    PERFORM public.fn_izo_montaj_marcheaza(v_ctx,to_jsonb(v_b),to_jsonb(v_dupa),to_jsonb(v_t));
    UPDATE public.magazie_bucati SET executie_teava_id=v_dupa.executie_teava_id,
      server_ver=v_dupa.server_ver,updated_at=v_dupa.updated_at WHERE id=v_b.id;
    GET DIAGNOSTICS v_randuri = ROW_COUNT;
    IF v_randuri<>1 THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    UPDATE public.executie_tevi SET serie_unica=v_t.serie_unica,sarja=v_t.sarja,lot=v_t.lot,
      lungime_m=v_t.lungime_m,lungime_originala_m=v_t.lungime_originala_m,
      tip=v_t.tip,dimensiune=v_t.dimensiune,unghi_curba=v_t.unghi_curba,updated_at=v_now WHERE id=p_teava;
    GET DIAGNOSTICS v_randuri = ROW_COUNT;
    IF v_randuri<>1 THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    UPDATE public.executie_pachete_lansare SET updated_at=v_now WHERE id=(v_p->>'id')::bigint;
    GET DIAGNOSTICS v_randuri = ROW_COUNT;
    IF v_randuri<>1 THEN RAISE EXCEPTION 'pachet_schimbat'; END IF;
    PERFORM public.fn_izo_montaj_marcheaza(NULL,NULL,NULL,NULL);
    RETURN jsonb_build_object('cod',CASE WHEN p_bucata IS NULL THEN 'dezlegat' ELSE 'legat' END,'pachet_updated_at',v_now);
  END $f$;

  CREATE FUNCTION public.fn_izo_pachet_leaga(p_teava bigint,p_bucata bigint,p_updated_at timestamptz) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  BEGIN
    IF p_bucata IS NULL THEN RAISE EXCEPTION 'bucata_lipsa'; END IF;
    RETURN public.fn_izo_flux_pachet_legatura(p_teava,p_bucata,p_updated_at,NULL,NULL);
  END $f$;
  CREATE FUNCTION public.fn_izo_pachet_dezleaga(p_teava bigint,p_motiv text,p_updated_at timestamptz,p_bucata_asteptata bigint) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
    SELECT public.fn_izo_flux_pachet_legatura(p_teava,NULL,p_updated_at,p_motiv,p_bucata_asteptata)
  $f$;

  -- E4b owns the approved weld graph and the operation journal. Until present, never infer a chain from weld numbers.
  CREATE FUNCTION public.fn_izo_flux_pachet_completeaza(p_cheie uuid,p_pachet bigint,p_updated_at timestamptz,p_sudura_de text,p_sudura_pana text)
    RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE v_lock jsonb;
  BEGIN
    IF p_cheie IS NULL OR p_updated_at IS NULL OR nullif(btrim(p_sudura_de),'') IS NULL OR nullif(btrim(p_sudura_pana),'') IS NULL THEN
      RAISE EXCEPTION 'parametri_invalizi'; END IF;
    v_lock:=public.fn_izo_flux_pachet_lock(NULL,p_pachet,p_updated_at);
    PERFORM public.fn_izo_flux_pachet_editabil(v_lock->'pachet');
    RAISE EXCEPTION 'completare_necesita_E4b_suduri_capete_jurnal';
  END $f$;
  CREATE FUNCTION public.fn_izo_pachet_completeaza(p_cheie uuid,p_pachet bigint,p_updated_at timestamptz,p_sudura_de text,p_sudura_pana text)
    RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
    SELECT public.fn_izo_flux_pachet_completeaza(p_cheie,p_pachet,p_updated_at,p_sudura_de,p_sudura_pana)
  $f$;

  REVOKE ALL ON FUNCTION public.fn_izo_flux_pachet_lock(bigint,bigint,timestamptz),public.fn_izo_flux_pachet_editabil(jsonb),
    public.fn_izo_flux_pachet_identitate(public.magazie_bucati),public.fn_izo_flux_pachet_legatura(bigint,bigint,timestamptz,text,bigint),
    public.fn_izo_flux_pachet_completeaza(uuid,bigint,timestamptz,text,text),public.fn_izo_pachet_leaga(bigint,bigint,timestamptz),
    public.fn_izo_pachet_dezleaga(bigint,text,timestamptz,bigint),public.fn_izo_pachet_completeaza(uuid,bigint,timestamptz,text,text) FROM PUBLIC,anon,authenticated,service_role;
  GRANT EXECUTE ON FUNCTION public.fn_izo_flux_pachet_lock(bigint,bigint,timestamptz),public.fn_izo_flux_pachet_editabil(jsonb),
    public.fn_izo_flux_pachet_identitate(public.magazie_bucati),public.fn_izo_flux_pachet_legatura(bigint,bigint,timestamptz,text,bigint),
    public.fn_izo_flux_pachet_completeaza(uuid,bigint,timestamptz,text,text) TO izo_montaj_writer;
  GRANT SELECT ON public.magazie_bucati,public.executie_tevi,public.executie_pachete_lansare TO izo_montaj_writer;
  GRANT UPDATE(executie_teava_id,server_ver,updated_at) ON public.magazie_bucati TO izo_montaj_writer;
  GRANT UPDATE(serie_unica,sarja,lot,lungime_m,lungime_originala_m,tip,dimensiune,unghi_curba,updated_at) ON public.executie_tevi TO izo_montaj_writer;
  GRANT UPDATE(updated_at) ON public.executie_pachete_lansare TO izo_montaj_writer;
  GRANT EXECUTE ON FUNCTION public.fn_izo_garda_scriitor(),public.fn_izo_nivel(bigint),public.fn_izo_tip_cod(integer) TO izo_montaj_writer;
  CREATE POLICY magbuc_izo_montaj_sel ON public.magazie_bucati FOR SELECT TO izo_montaj_writer USING (proiect_id IS NOT NULL);
  CREATE POLICY magbuc_izo_montaj_upd ON public.magazie_bucati FOR UPDATE TO izo_montaj_writer USING (proiect_id IS NOT NULL) WITH CHECK (proiect_id IS NOT NULL);
  CREATE POLICY executie_tevi_izo_montaj_sel ON public.executie_tevi FOR SELECT TO izo_montaj_writer USING (pachet_id IS NOT NULL);
  CREATE POLICY executie_tevi_izo_montaj_upd ON public.executie_tevi FOR UPDATE TO izo_montaj_writer USING (pachet_id IS NOT NULL) WITH CHECK (pachet_id IS NOT NULL);
  CREATE POLICY executie_pachete_izo_montaj_sel ON public.executie_pachete_lansare FOR SELECT TO izo_montaj_writer USING (proiect_id IS NOT NULL);
  CREATE POLICY executie_pachete_izo_montaj_upd ON public.executie_pachete_lansare FOR UPDATE TO izo_montaj_writer USING (proiect_id IS NOT NULL) WITH CHECK (proiect_id IS NOT NULL);
  GRANT CREATE ON SCHEMA public TO izo_montaj_writer;
  ALTER FUNCTION public.fn_izo_pachet_leaga(bigint,bigint,timestamptz) OWNER TO izo_montaj_writer;
  ALTER FUNCTION public.fn_izo_pachet_dezleaga(bigint,text,timestamptz,bigint) OWNER TO izo_montaj_writer;
  ALTER FUNCTION public.fn_izo_pachet_completeaza(uuid,bigint,timestamptz,text,text) OWNER TO izo_montaj_writer;
  REVOKE CREATE ON SCHEMA public FROM izo_montaj_writer;
  SET LOCAL ROLE izo_montaj_writer;
  GRANT EXECUTE ON FUNCTION public.fn_izo_pachet_leaga(bigint,bigint,timestamptz),public.fn_izo_pachet_dezleaga(bigint,text,timestamptz,bigint),
    public.fn_izo_pachet_completeaza(uuid,bigint,timestamptz,text,text) TO authenticated;
  RESET ROLE;


  CREATE FUNCTION public.fn_izo_porti_e4_definitii() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
    SELECT md5(concat_ws('|',
      (SELECT string_agg(format('%s:%s:%s:%s:%s:%s',p.oid::regprocedure,p.proowner,p.prosecdef,p.proconfig,p.proacl,md5(p.prosrc)),',' ORDER BY p.oid::regprocedure::text)
        FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND (p.proname LIKE 'fn_izo_flux_%' OR p.proname LIKE 'fn_izo_pachet_%' OR p.proname IN ('fn_izo_montaj_marcheaza','fn_izo_garda_montaj','fn_izo_seteaza_flux','fn_izo_porti_e4_definitii','fn_izo_porti_e4_lipsa'))),
      (SELECT string_agg(format('%s:%s:%s:%s',g.tgrelid::regclass,pg_get_triggerdef(g.oid),g.tgenabled,md5(p.prosrc)),',' ORDER BY g.tgrelid::regclass::text,g.tgname)
        FROM pg_trigger g JOIN pg_proc p ON p.oid=g.tgfoid WHERE NOT g.tgisinternal AND g.tgrelid IN
          ('public.executie_tevi'::regclass,'public.executie_pachete_lansare'::regclass,'public.executie_pachete_documente'::regclass,'public.executie_tronsoane'::regclass,'public.izo_tronson_config'::regclass,'storage.objects'::regclass)),
      (SELECT concat_ws(':',c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relacl) FROM pg_class c WHERE c.oid='public.izo_tronson_config'::regclass),
      (SELECT string_agg(format('%s:%s:%s:%s:%s:%s',a.attname,a.atttypid,a.attnotnull,a.attacl,a.attidentity,pg_get_expr(d.adbin,d.adrelid)),',' ORDER BY a.attnum)
        FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.izo_tronson_config'::regclass AND a.attnum>0 AND NOT a.attisdropped),
      (SELECT string_agg(pg_get_constraintdef(oid),',' ORDER BY conname) FROM pg_constraint WHERE conrelid='public.izo_tronson_config'::regclass),
      (SELECT string_agg(format('%s:%s:%s:%s:%s',polname,polcmd,polroles,pg_get_expr(polqual,polrelid),pg_get_expr(polwithcheck,polrelid)),',' ORDER BY polname) FROM pg_policy WHERE polrelid='public.izo_tronson_config'::regclass),
      (SELECT string_agg(pg_get_indexdef(indexrelid),',' ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid IN ('public.izo_tronson_config'::regclass,'public.profiles'::regclass)),
      (SELECT concat_ws(':',rolcanlogin,rolinherit,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolconfig) FROM pg_roles WHERE rolname='izo_montaj_writer'),
      (SELECT string_agg(format('%s:%s:%s:%s:%s',roleid,member,admin_option,inherit_option,set_option),',' ORDER BY roleid,member) FROM pg_auth_members WHERE roleid='izo_montaj_writer'::regrole OR member='izo_montaj_writer'::regrole)))
  $f$;
  CREATE FUNCTION public.fn_izo_porti_e4_lipsa() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_lipsa text[]:='{}';
  BEGIN
    IF public.fn_izo_porti_e4_definitii() IS DISTINCT FROM substring(obj_description('public.fn_izo_porti_e4_definitii()'::regprocedure,'pg_proc') FROM '^porti_e4=([0-9a-f]{32})$') THEN
      v_lipsa:=array_append(v_lipsa,'E4 definitii diferite'); END IF;
    IF has_schema_privilege('izo_montaj_writer','public','CREATE') OR EXISTS
      (SELECT 1 FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind='S'
       AND has_sequence_privilege('izo_montaj_writer',c.oid,'USAGE') IS DISTINCT FROM (c.oid='public.izo_server_ver_seq'::regclass))
      THEN v_lipsa:=array_append(v_lipsa,'E4 ACL schema/secvente'); END IF;
    IF EXISTS(SELECT 1 FROM pg_trigger g WHERE g.tgname LIKE 'a0_izo_flux_%' AND g.tgenabled<>'A') THEN v_lipsa:=array_append(v_lipsa,'E4 trigger dezactivat'); END IF;
    IF EXISTS(SELECT 1 FROM pg_trigger g JOIN pg_trigger e ON e.tgrelid=g.tgrelid
      WHERE e.tgname IN ('a0_izo_flux_tevi','a0_izo_flux_pachete','a0_izo_flux_documente')
        AND NOT g.tgisinternal AND (g.tgtype::integer & 2)=2 AND g.tgname<e.tgname) THEN v_lipsa:=array_append(v_lipsa,'E4 ordinea BEFORE'); END IF;
    RETURN v_lipsa;
  END $f$;
  REVOKE ALL ON FUNCTION public.fn_izo_porti_e4_definitii(),public.fn_izo_porti_e4_lipsa() FROM PUBLIC,anon,authenticated,service_role;
    CREATE OR REPLACE FUNCTION public.fn_izo_porti_lipsa() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v text[] := '{}'; r record;
  BEGIN
    -- triggerele: există și sunt ENABLE ALWAYS ('A' — trag și sub session_replication_role = replica)
    FOR r IN SELECT x.tabel, x.trg, g.tgenabled
               FROM (VALUES ('magazie_bucati','trg_magbuc_izo_garda'), ('magazie_bucati','trg_magbuc_izo_truncate'),
                            ('magazie_bucati_evenimente','trg_izo_ev_garda'), ('magazie_bucati_evenimente','trg_izo_ev_truncate'),
                            ('magazie_bucati_miscari','trg_izo_mis_garda'), ('magazie_bucati_miscari','trg_izo_mis_truncate'),
                            ('izo_importuri','trg_izo_imp_garda'), ('izo_importuri','trg_izo_imp_truncate'),
                            ('izo_proiect_config','trg_izo_cfg_garda'), ('izo_proiect_config','trg_izo_cfg_truncate'),
                            ('izo_atribuiri','trg_izo_atr_garda'), ('izo_atribuiri','trg_izo_atr_truncate'),
                            ('executie_tevi','trg_executie_tevi_izo_delete'), ('executie_tevi','trg_executie_tevi_izo_mutare'),
                            ('executie_pachete_lansare','trg_pachete_izo_delete'), ('executie_pachete_lansare','trg_pachete_izo_mutare'),
                            ('executie_tronsoane','trg_tronsoane_izo_mutare'), ('logistica_depozite','trg_depozite_izo_mutare'),
                            ('executie_proiecte','trg_proiecte_izo_site'),
                            ('executie_tevi','trg_executie_tevi_izo_truncate'), ('executie_pachete_lansare','trg_pachete_izo_truncate'),
                            ('executie_bonuri_consum_linii','trg_bon_linii_izo_bucata')) x(tabel, trg)
               LEFT JOIN pg_trigger g ON g.tgname = x.trg AND g.tgrelid = to_regclass('public.' || x.tabel) AND NOT g.tgisinternal
    LOOP
      IF r.tgenabled IS DISTINCT FROM 'A' THEN v := array_append(v, format('trigger %s.%s (%s)', r.tabel, r.trg, coalesce(r.tgenabled::text, 'lipsă'))); END IF;
    END LOOP;
    -- RLS activ pe tabelele registrului și pe magazie_bucati
    FOR r IN SELECT t.n, c.relrowsecurity FROM unnest(ARRAY['magazie_bucati','izo_proiect_config','izo_atribuiri','izo_importuri',
                      'magazie_bucati_evenimente','magazie_bucati_miscari']) t(n) LEFT JOIN pg_class c ON c.oid = to_regclass('public.' || t.n)
    LOOP
      IF r.relrowsecurity IS NOT TRUE THEN v := array_append(v, format('RLS inactiv pe %s', r.n)); END IF;
    END LOOP;
    -- politicile RESTRICTIVE ale clientului pe magazie_bucati
    IF (SELECT count(*) FROM pg_policy p WHERE p.polrelid = 'public.magazie_bucati'::regclass AND NOT p.polpermissive
          AND p.polname IN ('magbuc_izo_client_sel','magbuc_izo_client_ins','magbuc_izo_client_upd','magbuc_izo_client_del')) <> 4 THEN
      v := array_append(v, 'politicile RESTRICTIVE magbuc_izo_client_*');
    END IF;
    -- rolul scriitor: fără BYPASSRLS/LOGIN/SUPERUSER/INHERIT; singurul membru = postgres; niciun rol API nu-l poate prelua
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'izo_registru_writer' AND NOT rolbypassrls AND NOT rolcanlogin AND NOT rolsuper AND NOT rolinherit) THEN
      v := array_append(v, 'rolul izo_registru_writer (lipsă sau BYPASSRLS/LOGIN/SUPERUSER/INHERIT)');
    -- membri: doar postgres (PG16+: CREATE ROLE de către un non-superuser adaugă automat un rând ADMIN fără SET/INHERIT,
    -- grantor = superuser-ul de bootstrap — pe Supabase supabase_admin; găsit de testul pe branch PG17); SET da, INHERIT nu
    ELSIF EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'izo_registru_writer'::regrole AND m.member <> 'postgres'::regrole)
       OR NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'izo_registru_writer'::regrole AND m.member = 'postgres'::regrole AND m.set_option)
       OR EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'izo_registru_writer'::regrole AND m.inherit_option)
       OR EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role','authenticator']) a(n)
                   WHERE EXISTS (SELECT 1 FROM pg_roles WHERE rolname = a.n) AND pg_has_role(a.n, 'izo_registru_writer', 'MEMBER')) THEN
      v := array_append(v, 'membrii rolului izo_registru_writer');
    END IF;
    -- ACL: clientul nu scrie tabelele registrului și nu execută funcțiile writer-ului
    IF EXISTS (SELECT 1 FROM unnest(ARRAY['izo_proiect_config','izo_atribuiri','izo_importuri','magazie_bucati_evenimente','magazie_bucati_miscari']) t(n),
                             unnest(ARRAY['anon','authenticated','service_role']) a(n), unnest(ARRAY['INSERT','UPDATE','DELETE','TRUNCATE']) p(n)
                WHERE to_regclass('public.' || t.n) IS NULL OR has_table_privilege(a.n, 'public.' || t.n, p.n)) THEN
      v := array_append(v, 'ACL de scriere pe tabelele registrului');
    END IF;
    IF EXISTS (SELECT 1 FROM pg_proc p, unnest(ARRAY['anon','authenticated','service_role']) a(n)
                WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('fn_izo_seteaza_nivel','fn_izo_import_sold_initial','fn_izo_import_storno','fn_izo_activeaza_si_importa')
                  AND has_function_privilege(a.n, p.oid, 'EXECUTE')) THEN
      v := array_append(v, 'EXECUTE din API pe funcțiile registrului');
    END IF;
    -- allowlist pe ACL (invariantul principal, Copilot r6 c): intrările writer-ului se execută DOAR de owner și postgres
    IF EXISTS (SELECT 1 FROM pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                WHERE p.pronamespace = 'public'::regnamespace
                  AND p.proname IN ('fn_izo_seteaza_nivel','fn_izo_import_sold_initial','fn_izo_import_storno','fn_izo_activeaza_si_importa')
                  AND a.privilege_type = 'EXECUTE' AND (a.grantee = 0 OR pg_get_userbyid(a.grantee) NOT IN ('izo_registru_writer','postgres'))) THEN
      v := array_append(v, 'EXECUTE pe funcțiile registrului pentru alt rol decât writer / postgres (allowlist)');
    END IF;
    -- wrapper-e (plasă de siguranță peste allowlist): o funcție cu alt owner decât writer-ul sau un view / o regulă care cheamă funcțiile registrului ar
    -- deveni o cale nouă spre ele (Codex r5 6) — acceptate doar după review, cu actualizarea acestei porți
    IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.proowner <> 'izo_registru_writer'::regrole
                AND p.oid <> 'public.fn_izo_porti_lipsa()'::regprocedure   -- poarta însăși le numește în verificarea ACL
                -- corpul complet: prosrc (plpgsql / sql clasic) + corpul BEGIN ATOMIC (prosrc gol, corpul în prosqlbody) — review r7
                AND (p.prosrc || ' ' || coalesce(pg_get_function_sqlbody(p.oid), ''))
                    ~* 'fn_izo_(seteaza_nivel|import_sold_initial|import_storno|activeaza_si_importa)')   -- fără majuscule (N3)
       OR EXISTS (SELECT 1 FROM pg_rewrite rw WHERE pg_get_ruledef(rw.oid) ~* 'fn_izo_(seteaza_nivel|import_sold_initial|import_storno|activeaza_si_importa)') THEN
      v := array_append(v, 'o funcție / un view din afara writer-ului cheamă funcțiile registrului (wrapper nerevizuit)');
    END IF;
    -- CITIRILE (acțiunea 6, Codex r4 / Jakarinos r6–r10): filtrarea citirii (RLS restrictiv + fn_izo_citire) se poate ocoli
    -- fără niciun trigger de scriere printr-un view cu drepturile ownerului sau printr-o funcție DEFINER care întoarce rânduri.
    -- Inventarul de pe live (docs/izometrie/E2A_INVENTAR_CITIRI.md, 21.10.2026): 0 view-uri, 0 funcții care ating
    -- magazie_bucati, 5 DEFINER cu SQL dinamic pe tabele fixe (profiles / executie_proiecte), neexpuse. Porțile de mai jos
    -- refuză activarea dacă apare ceva nou, nerevizuit (r11: porți pe tipuri; r12: închiderea tranzitivă de mai jos):
    -- r12 (Jakarinos + Copilot r11): ÎNCHIDEREA TRANZITIVĂ a tot ce poate citi registrul, până la punct fix:
    --   sămânța = tabelele registrului + funcțiile cu SQL dinamic (pot citi orice tabel) din afara listei revizuite;
    --   se adaugă repetat: view-urile / view-urile materializate care depind (pg_depend → pg_rewrite) de ceva din închidere
    --   (inclusiv cele security_invoker — un DEFINER care le citește le ocolește RLS-ul), și funcțiile (orice schemă
    --   non-sistem, în afara public.fn_izo_*) al căror corp NUMEȘTE ceva din închidere (în public: numele simplu; în alte
    --   scheme: schema.nume) sau depind de el în catalog (corpuri BEGIN ATOMIC).
    -- Refuz dacă în închidere apare: un view fără security_invoker, un view materializat sau o funcție SECURITY DEFINER.
    -- Funcțiile DEFINER cu SQL dinamic din afara listei revizuite sunt refuzate oricum (citesc orice, fără să numească).
    DECLARE
      c_rel oid[]; c_fn oid[] := '{}'; v_marime int := -1; v_iter int := 0; c_mut oid[] := '{}';
      -- funcțiile DEFINER cu SQL dinamic revizuite pe live (docs/izometrie/E2A_INVENTAR_CITIRI.md, 21.10.2026): tabele fixe
      -- (executie_proiecte / profiles), identificatori pe listă albă. Amprenta excepției = md5(prosrc | proconfig | owner |
      -- proacl | prosecdef) (Jakarinos r12): orice schimbare de corp, search_path, owner sau drepturi cere review
      c_dinamice_revizuite text[] := ARRAY[
        '_completare_goleste_camp(bigint,text,integer)=888fde4d4e7fbea6889835dd96c2225d',
        '_completare_scrie_camp(bigint,text,text)=77d7b091a049ccc86b47d078957db39f',
        'fn_cont_inchide(uuid,text,text,integer)=c4a6ca93a52ca8a97aa90f168debf30e',
        'fn_cont_restaureaza_flaguri(uuid,jsonb)=ecd803a2dda6b734ea92ebaf10564397',
        'fn_conturi_inchideri_sweep()=402874ea5081b41801313e0def9e3226',
        'fn_tichete_notif_on_insert()=1ffa41a8750b6d48d721d9e2a00b3f54'];
      -- limitele unui identificator, inclusiv citat („"teste".f()”), fără \m / \M (ghilimelele nu sunt caractere de cuvânt)
      c_st constant text := '(^|[^[:alnum:]_$"])"?';
      c_dr constant text := '"?($|[^[:alnum:]_$])';
      -- schemele platformei Supabase: obiectele lor din închidere (funcții INVOKER cu SQL dinamic: realtime.cast, storage.search…)
      -- se potrivesc necalificat DOAR când schema e în search_path-ul funcției; ale noastre (orice altă schemă) se potrivesc
      -- necalificat ÎNTOTDEAUNA — conservator, fals-pozitivele sunt acceptate (Copilot r12 P1)
      c_scheme_platforma constant text[] := ARRAY['auth','storage','realtime','extensions','graphql','graphql_public','vault','net',
                                                  'supabase_functions','supabase_migrations','pgbouncer','pgsodium','pgsodium_masks','cron'];
      -- r5d (20261103b): aceeași semantică, evaluare SEMI-NAIVĂ — fiecare element nou al închiderii se caută o singură dată,
      -- cu alternanța numelor din frontieră (r5f: pe bucăți mărginite, nu o singură expresie); corpurile se citesc o dată
      k_oid oid[]; k_corp text[]; k_cale text[]; f_rel oid[]; f_fn oid[]; f_mut oid[]; n_rel oid[]; n_fn oid[]; n_mut oid[];
      -- r5f (#825 NO-GO): tiparele frontierei, pe bucăți: a_x = alternanța (≤ ~4000 de caractere), a_s = schema de platformă
      -- căreia i se aplică (NULL = oricărei funcții)
      a_s text[]; a_x text[];
      k_i int; k_n int; k_s text; k_s2 text; k_adanc oid[] := '{}';
      -- r5g (#825) NO-GO P2: o schemă a platformei urmată (după ghilimele / spații / un punct opțional) de deschiderea unui
      -- comentariu — singura formă în care un comentariu rupe apelul ei calificat
      k_com text := c_st || '(' || array_to_string(c_scheme_platforma, '|') || ')"?[[:space:]]*(\.[[:space:]]*)?(/\*|--)';
      -- r5g (#825) NO-GO P1-D: invocările implicite revizuite, de pe prod — singurele obiecte din catalog care cheamă implicit o
      -- funcție din închiderea de pe prod sau (r5h) un mutator de cale; citite read-only 22.10.2026 (baseline_pre_e3.json, cheia
      -- „implicite”). r5h (#825 r5g NO-GO, Jak P1): amprenta = md5(tip | identitate | funcția | owner | SECURITY DEFINER |
      -- proconfig | limbaj | md5(corp)) — CU corpul: un corp schimbat (același owner / config) nu mai păstrează excepția. Un
      -- upgrade Supabase care schimbă corpul uneia dintre funcțiile de platformă înroșește poarta (fail-closed): captură nouă
      -- + review + migrare (design §17)
      c_implicite_revizuite constant text[] := ARRAY[
        'event trigger issue_graphql_placeholder=2aa685a004bc87f7a10ef72d134a88bb',
        'event trigger issue_pg_graphql_access=7ed4741489f49636791f930411cfb345',
        'event trigger issue_pg_net_access=d62f8ab601b809080c679266fbdb8a06',
        'trigger a01_ofertare_cantitati_lot_canonic on public.ofertare_cantitati=62d07782ee60e73b327be8c82d4dd34b',
        'trigger a01_ofertare_cerinte_lot_canonic on public.ofertare_cerinte=b2b9b1f753fae9e4f8a7a10ee6c6b351',
        'trigger on_auth_user_created on auth.users=5f3f59717d56d1148ac3f4b7d3a2b199',
        'trigger prevent_role_escalation_trigger on public.profiles=06b7e4fcaab58c9a3faecb7ff4856b45',
        'trigger tr_check_filters on realtime.subscription=ed76f4ff4e3c6abd998eded3d159d3c3',
        'trigger trg_employees_persoana_lock on public.employees=9dcecd0c70efdf1bf5e24e9c1157bc11',
        'trigger trg_employees_zz_ciclu_cont on public.employees=8b5dbbd69476106544cff2b5393c116a',
        'trigger trg_enforce_owner_only_salary_flags on public.profiles=46f1b6af2f30d56993ca988b267e76d8',
        'trigger trg_hr_autorizatii_rsvti_doar_rpc on public.hr_autorizatii=9a7f49627ab4e62e14aa43252a2ab56e',
        'trigger trg_hr_employees_private_persoana_lock on public.hr_employees_private=32261dc19c5d0da91f0487ab2f33bb08',
        'trigger trg_profiles_campuri_owner_only on public.profiles=e80a3aed6ff3f2055785bdc974702cd5',
        'trigger trg_protect_can_access_pontaj_brut on public.profiles=3a58112eec4c06bef2d66159ad6f82a5'];
    BEGIN
      SELECT array_agg(c.oid) INTO c_rel FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace
         AND c.relname IN ('magazie_bucati','izo_proiect_config','izo_atribuiri','izo_importuri','magazie_bucati_evenimente','magazie_bucati_miscari');
      -- funcțiile cu SQL dinamic (orice EXECUTE), în afara registrului și a listei revizuite: în închidere de la început
      SELECT coalesce(array_agg(p.oid), '{}') INTO c_fn FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_' AND p.prolang NOT IN (12, 13)
         AND NOT (n.nspname = 'public' AND p.proname LIKE 'fn\_izo\_%')
         AND (p.prosrc || ' ' || coalesce(pg_get_function_sqlbody(p.oid), '')) ~* '\mexecute\M'
         AND format('%s=%s', p.oid::regprocedure::text, md5(p.prosrc || '|' || coalesce(p.proconfig::text, '') || '|' || pg_get_userbyid(p.proowner)
                                                           || '|' || coalesce(p.proacl::text, '') || '|' || p.prosecdef::text))
             <> ALL (c_dinamice_revizuite);
      -- r5f (#825): + tabelele documentelor E3 — RLS cu citire prin fn_izo_citire, ca registrul (design §13.2): un DEFINER /
      -- un view fără security_invoker / un lanț din afara fn_izo_* care ajunge la ele e refuzat la fel. Funcțiile E3 legitime
      -- (fn_izo_doc_* / fn_izo_scan_*, owner izo_doc_editor / izo_receptie_writer / postgres) sunt fn_izo_*: în afara
      -- închiderii, ca la E2a, și acoperite de ștampila E2a (fn_izo_porti_definitii: owner, corp, config, ACL)
      c_rel := c_rel || ARRAY(SELECT c.oid FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace
         AND c.relname IN ('izo_documente_intrare','izo_documente_intrare_randuri','izo_documente_scanuri'));
      -- r5g (#825) NO-GO P1-C: + TOATE funcțiile public.fn_izo_* ca ȚINTE (nu candidați): cititorii INVOKER ai documentelor
      -- (owner postgres) și DEFINER-ele interne citesc ce RLS-ul ascunde; un DEFINER / view / lanț din afara fn_izo_* care le
      -- cheamă (după nume, BEGIN ATOMIC, view, operator / cast / agregat) intră în închidere, ca un cititor direct. După
      -- propagare ele ies din c_fn (mai jos): sunt API-ul revizuit, sub ștampila E2a. Invocările lor implicite din catalog
      -- (trigger / politică / DEFAULT / CHECK …) sunt fixate de ștampila E3 (fn_izo_porti_e3_definitii)
      c_fn := c_fn || ARRAY(SELECT p.oid FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname LIKE 'fn\_izo\_%');
      -- corpurile candidate (orice schemă non-sistem, în afara public.fn_izo_*), o singură dată; calea fixată în proconfig
      -- (NULL = necunoscută: funcția moștenește calea apelantului)
      SELECT coalesce(array_agg(p.oid ORDER BY p.oid), '{}'),
             coalesce(array_agg(p.prosrc || ' ' || coalesce(pg_get_function_sqlbody(p.oid), '') ORDER BY p.oid), '{}'),
             coalesce(array_agg((SELECT array_to_string(string_to_array(lower(regexp_replace(substr(c, 13), '[[:space:]"]', '', 'g')), ','), ',')
                                   FROM unnest(p.proconfig) c WHERE c LIKE 'search\_path=%' LIMIT 1) ORDER BY p.oid), '{}')
        INTO k_oid, k_corp, k_cale
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_' AND p.prolang NOT IN (12, 13)
         AND NOT (n.nspname = 'public' AND p.proname LIKE 'fn\_izo\_%');
      -- r5f (#825 NO-GO): un comentariu între schemă și nume („storage/**/.f()”, „storage -- x⏎.f()”) ascunde forma calificată —
      -- contează la schemele platformei, unde necalificatul cere calea. Corpului i se adaugă o copie fără comentarii (blocurile
      -- imbricate din interior spre exterior, până la punct fix; apoi „--” până la capăt de rând). Copia doar ADAUGĂ potriviri
      -- (originalul rămâne): un „/*” sau „--” dintr-un șir taie din copie, nu din original. Cel mult 20 de niveluri (fiecare nivel
      -- = o trecere peste tot corpul — fără plafon, mii de comentarii imbricate ar ține poarta minute întregi): mai adânc → corpul
      -- nu se poate citi sigur, intră în sămânță ca SQL-ul dinamic (k_adanc, mai jos)
      -- r5g (#825, Copilot P1): copia nu înțelege literalii — un „--” / „/*” dintr-un șir taie din copie chiar apelul ascuns
      -- de comentariu („x := '--'; PERFORM storage /* c */ . f();”), iar originalul nu-l are calificat. Fail-closed, fără
      -- tokenizer: calea devine NECUNOSCUTĂ (NULL, în ambele bucle) și numele schemei se potrivesc în corp necalificat.
      -- r5g (#825) NO-GO P2: nu la orice „/*” / „--” (pe prod: 192 de corpuri, 162 DEFINER — un comentariu + „CAST(” /
      -- „send” / „search” ar fi înroșit poarta), ci doar când o schemă a platformei e urmată de deschiderea unui comentariu
      -- (k_com), pe ORIGINAL: comentariul care rupe apelul apare textual acolo, deci un literal nu-l poate ascunde; pe prod: 0
      -- corpuri. La celelalte scheme necalificatul se potrivește oricum, deci forma calificată ruptă nu ascunde nimic
      FOR k_i IN 1 .. cardinality(k_corp) LOOP
        IF k_corp[k_i] ~* k_com THEN k_cale[k_i] := NULL; END IF;
        k_s := k_corp[k_i]; k_n := 0;
        LOOP
          k_s2 := regexp_replace(k_s, '/\*([^*/]|\*+[^*/]|/+[^*/])*\*+/', ' ', 'g');
          EXIT WHEN k_s2 = k_s;
          k_s := k_s2; k_n := k_n + 1;
          IF k_n >= 20 THEN k_adanc := k_adanc || k_oid[k_i]; EXIT; END IF;
        END LOOP;
        k_s := regexp_replace(k_s, '--[^\n]*', ' ', 'g');
        IF k_s <> k_corp[k_i] THEN k_corp[k_i] := k_corp[k_i] || ' ' || k_s; END IF;
      END LOOP;
      -- r5f (#825 NO-GO): în sămânță și funcțiile care pot citi un tabel FĂRĂ să-i scrie numele și fără EXECUTE — identificatori
      -- U&"…" (escape-uri Unicode), SQL dat ca text (query/table/schema/database_to_xml, ts_stat / ts_rewrite, crosstab /
      -- connectby, dblink), fișierele / paginile tabelelor (pg_read_[binary_]file, lo_import, get_raw_page); ca SQL-ul
      -- dinamic: un DEFINER care le conține (sau le cheamă) e refuzat. Mai strict decât E2a, care le lasă verzi. Tot aici:
      -- corpurile cu comentarii imbricate peste plafon (k_adanc)
      c_fn := c_fn || ARRAY(SELECT k.oid FROM unnest(k_oid, k_corp) k(oid, corp) WHERE k.oid <> ALL (c_fn)
                              AND (k.oid = ANY (k_adanc)
                                   OR k.corp ~* ('u&"|\m(query|table|schema|database)_to_xml|\mts_(stat|rewrite)\M|\m(crosstab|connectby|dblink)'
                                                 || '|\mpg_read_(binary_)?file\M|\mlo_import\M|\mget_raw_page\M')));
      -- mutatorii de cale (r15): sămânța = corp cu set_config / search_path; propagați până la punct fix
      SELECT coalesce(array_agg(k.oid), '{}') INTO c_mut FROM unnest(k_oid, k_corp) k(oid, corp) WHERE k.corp ~* '(set_config|search_path)';
      f_mut := c_mut; v_iter := 0;
      WHILE cardinality(f_mut) > 0 AND v_iter < 100 LOOP
        v_iter := v_iter + 1;
        -- r5f (#825 NO-GO): tiparele pe BUCĂȚI de ~4000 de caractere, nu o singură alternanță: cu ~1000 de nume lungi în
        -- frontieră, motorul de regex refuză („invalid memory alloc request size” / „regular expression is too complex”) —
        -- poarta ar da eroare unde E2a răspunde (testul „frontieră largă”), iar compilarea crește pătratic. Fiecare nume dă două
        -- alternative: calificat (s = NULL, oricui) și necalificat (s = NULL în afara platformei; s = schema platformei: doar
        -- dacă e în calea fixată a funcției sau calea e nefixată).
        -- r5f (#825 NO-GO, P1): și SCHEMA se escapează (nsx), ca numele: o schemă construită („x)(?=x)y(x”) ar închide grupul
        -- comun și ar face bucata (deci toate numele ei) imposibil de potrivit — verde fals; nsp (brut) rămâne doar pentru s
        WITH t AS (SELECT n2.nspname::text nsp, regexp_replace(n2.nspname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nsx,
                          regexp_replace(q.proname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nume
                     FROM pg_proc q JOIN pg_namespace n2 ON n2.oid = q.pronamespace WHERE q.oid = ANY (f_mut)),
             y AS (SELECT NULL::text s, t.nsx || '"?[[:space:]]*\.[[:space:]]*"?' || t.nume f FROM t
                   UNION ALL SELECT CASE WHEN t.nsp = ANY (c_scheme_platforma) THEN t.nsp END, t.nume FROM t)
        SELECT coalesce(array_agg(z.s), '{}'), coalesce(array_agg(c_st || '(' || z.alt || ')' || c_dr), '{}') INTO a_s, a_x
          FROM (SELECT y2.s, string_agg(y2.f, '|') alt
                  FROM (SELECT y.s, y.f, (sum(length(y.f) + 1) OVER (PARTITION BY y.s ORDER BY y.f ROWS UNBOUNDED PRECEDING) - 1) / 4000 b FROM y) y2
                 GROUP BY y2.s, y2.b) z;
        -- bucata în exterior (LATERAL … OFFSET 0: nu se aplatizează), corpurile în interior — fiecare tipar se compilează o dată;
        -- CASE fixează ordinea: întâi filtrele ieftine, regex-ul ultimul (planificatorul l-ar evalua primul)
        n_mut := ARRAY(SELECT DISTINCT m.oid FROM unnest(a_s, a_x) p(s, x)
                         CROSS JOIN LATERAL (SELECT k.oid FROM unnest(k_oid, k_corp, k_cale) k(oid, corp, cale)
                                              WHERE CASE WHEN k.oid = ANY (c_mut) THEN false
                                                         WHEN p.s IS NULL OR k.cale IS NULL OR p.s = ANY (string_to_array(k.cale, ',')) THEN k.corp ~* p.x
                                                         ELSE false END OFFSET 0) m);
        c_mut := c_mut || n_mut; f_mut := n_mut;
      END LOOP;
      IF v_iter >= 100 THEN v := array_append(v, 'propagarea mutatorilor de cale nu converge (citire nerevizuită)'); END IF;
      -- închiderea: frontiera = elementele adăugate în iterația precedentă (view-urile noi intră în frontiera aceleiași iterații,
      -- ca în E2a, unde sunt adăugate înaintea funcțiilor)
      f_rel := c_rel; f_fn := c_fn; v_iter := 0;
      WHILE (cardinality(f_rel) > 0 OR cardinality(f_fn) > 0) AND v_iter < 100 LOOP
        v_iter := v_iter + 1;
        n_rel := ARRAY(SELECT DISTINCT rw.ev_class FROM pg_depend d JOIN pg_rewrite rw ON rw.oid = d.objid
                        WHERE d.classid = 'pg_rewrite'::regclass
                          AND ((d.refclassid = 'pg_class'::regclass AND d.refobjid = ANY (f_rel))
                               OR (d.refclassid = 'pg_proc'::regclass AND d.refobjid = ANY (f_fn)))
                          AND rw.ev_class <> ALL (c_rel));
        c_rel := c_rel || n_rel; f_rel := f_rel || n_rel;
        -- r5f (#825 NO-GO): aceleași bucăți de tipare ca la mutatori, cu schema escapată (P1; vezi mai sus)
        WITH t AS (SELECT n2.nspname::text nsp, regexp_replace(n2.nspname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nsx,
                          regexp_replace(c.relname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nume
                     FROM pg_class c JOIN pg_namespace n2 ON n2.oid = c.relnamespace WHERE c.oid = ANY (f_rel)
                   UNION
                   SELECT n2.nspname::text, regexp_replace(n2.nspname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g'),
                          regexp_replace(q.proname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g')
                     FROM pg_proc q JOIN pg_namespace n2 ON n2.oid = q.pronamespace WHERE q.oid = ANY (f_fn)),
             y AS (SELECT NULL::text s, t.nsx || '"?[[:space:]]*\.[[:space:]]*"?' || t.nume f FROM t
                   UNION ALL SELECT CASE WHEN t.nsp = ANY (c_scheme_platforma) THEN t.nsp END, t.nume FROM t)
        SELECT coalesce(array_agg(z.s), '{}'), coalesce(array_agg(c_st || '(' || z.alt || ')' || c_dr), '{}') INTO a_s, a_x
          FROM (SELECT y2.s, string_agg(y2.f, '|') alt
                  FROM (SELECT y.s, y.f, (sum(length(y.f) + 1) OVER (PARTITION BY y.s ORDER BY y.f ROWS UNBOUNDED PRECEDING) - 1) / 4000 b FROM y) y2
                 GROUP BY y2.s, y2.b) z;
        -- schemele platformei: necalificat doar dacă schema e în calea funcției; calea e necunoscută dacă nu e fixată SAU dacă
        -- funcția e mutator (r15)
        n_fn := ARRAY(SELECT DISTINCT m.oid FROM unnest(a_s, a_x) p(s, x)
                        CROSS JOIN LATERAL (SELECT k.oid FROM unnest(k_oid, k_corp, k_cale) k(oid, corp, cale)
                                             WHERE CASE WHEN k.oid = ANY (c_fn) THEN false
                                                        WHEN p.s IS NULL OR k.oid = ANY (c_mut) OR k.cale IS NULL OR p.s = ANY (string_to_array(k.cale, ','))
                                                          THEN k.corp ~* p.x
                                                        ELSE false END OFFSET 0) m);
        -- sau depind de ceva din frontieră în catalog (BEGIN ATOMIC)
        n_fn := n_fn || ARRAY(SELECT k.oid FROM unnest(k_oid) k(oid) WHERE k.oid <> ALL (c_fn) AND k.oid <> ALL (n_fn)
                                AND EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid = 'pg_proc'::regclass AND d.objid = k.oid
                                               AND ((d.refclassid = 'pg_class'::regclass AND d.refobjid = ANY (f_rel))
                                                    OR (d.refclassid = 'pg_proc'::regclass AND d.refobjid = ANY (f_fn)))));
        c_fn := c_fn || n_fn;
        f_rel := n_rel; f_fn := n_fn;
      END LOOP;
      IF v_iter >= 100 THEN v := array_append(v, 'închiderea citirilor nu converge (citire nerevizuită)'); END IF;
      -- r5f (#825 NO-GO, P1): un element al închiderii (sau mutator) al cărui nume nu se poate căuta sigur în corpuri → refuz:
      -- schemă cu caractere speciale de regex (E2a dă eroare pe ea, deci rămâne închisă — poarta nouă refuză la fel, nu dă
      -- verde) sau ghilimele în schemă / nume (în corp apar dublate, „"x""y"” — nicio expresie nu le găsește; în E2a: verde fals)
      IF EXISTS (SELECT 1 FROM (SELECT c.relname::text nume, c.relnamespace ns FROM pg_class c WHERE c.oid = ANY (c_rel)
                                UNION ALL SELECT q.proname::text, q.pronamespace FROM pg_proc q WHERE q.oid = ANY (c_fn || c_mut)) o
                  JOIN pg_namespace n2 ON n2.oid = o.ns
                 WHERE n2.nspname ~ '[.^$*+?()\[\]{}|\\"]' OR o.nume ~ '"') THEN
        v := array_append(v, 'un nume din închiderea citirilor nu se poate căuta sigur în corpuri (schemă cu caractere speciale de regex / nume cu ghilimele) (citire nerevizuită)');
      END IF;
      -- r5g (#825, Jak P1): invocarea IMPLICITĂ cheamă o funcție fără să-i scrie numele — operatorul (oprcode / oprrest /
      -- oprjoin: „OPERATOR(s.#!#) x”, infix / prefix), cast-ul (castfunc: „x::tip”), agregatul (aggtransfn / aggfinalfn /
      -- aggcombinefn / aggserialfn / aggdeserialfn / aggmtransfn / aggminvtransfn / aggmfinalfn; agregatul e prolang
      -- internal, deci nu e candidat și numele lui nu se caută); corpurile ne-ATOMIC n-au nici dependențe în catalog. Nu se
      -- propagă (forma infix nu se poate căuta sigur în corpuri): funcția-suport în închidere sau mutator de cale → refuz
      -- explicit, oricine ar folosi operatorul / cast-ul / agregatul (fals-pozitive acceptate). Pe prod: 0 (suportul din afara
      -- pg_catalog e doar C, în extensions — niciodată candidat). Celelalte obiecte din catalog: regula P1-D, mai jos
      FOR k_s IN SELECT x.d FROM (
          SELECT format('operator %s → %s', o.oid::regoperator, f.f::regprocedure) d
            FROM pg_operator o CROSS JOIN LATERAL unnest(ARRAY[o.oprcode::oid, o.oprrest::oid, o.oprjoin::oid]) f(f)
           WHERE f.f = ANY (c_fn || c_mut)
          UNION
          SELECT format('cast (%s AS %s) → %s', c.castsource::regtype, c.casttarget::regtype, c.castfunc::regprocedure)
            FROM pg_cast c WHERE c.castfunc = ANY (c_fn || c_mut)
          UNION
          SELECT format('agregat %s → %s', a.aggfnoid::regprocedure, f.f::regprocedure)
            FROM pg_aggregate a CROSS JOIN LATERAL unnest(ARRAY[a.aggtransfn::oid, a.aggfinalfn::oid, a.aggcombinefn::oid, a.aggserialfn::oid,
                                                                a.aggdeserialfn::oid, a.aggmtransfn::oid, a.aggminvtransfn::oid, a.aggmfinalfn::oid]) f(f)
           WHERE f.f = ANY (c_fn || c_mut)) x
        ORDER BY x.d COLLATE "C"
      LOOP
        v := array_append(v, 'invocare implicită neanalizată: ' || k_s || ' (funcție-suport din închiderea citirilor sau mutator de cale) (citire nerevizuită)');
      END LOOP;
      -- r5g (#825) NO-GO P1-C: țintele fn_izo_* ies din c_fn după propagare (API-ul revizuit, sub ștampila E2a; un DEFINER
      -- fn_izo_* nu e „DEFINER din afara registrului”). Fără sămânța E3 c_fn nu conține fn_izo_* (nici candidați, nici
      -- SQL dinamic), deci aici nu schimbă nimic
      c_fn := ARRAY(SELECT x.f FROM unnest(c_fn) x(f) JOIN pg_proc q ON q.oid = x.f
                     WHERE NOT (q.pronamespace = 'public'::regnamespace AND q.proname LIKE 'fn\_izo\_%'));
      -- r5g (#825) NO-GO P1-D: invocarea implicită prin EXPRESII DIN CATALOG — CHECK pe domeniu / tabel, DEFAULT, coloană
      -- generată, expresie de index, trigger (și event trigger), politică, statistici, I/O de tip, clasă de operatori …: un
      -- DEFINER care scrie / convertește / sortează le pornește fără să numească funcția. Orice rând pg_depend spre o funcție
      -- din închidere al cărui obiect nu e propagat mai sus (view / regulă: pg_rewrite; funcție: pg_proc — candidații prin
      -- propagare, agregatele prin regula de deasupra; operator / cast: regula de deasupra) → refuz explicit, cu obiectul numit,
      -- în afara listei revizuite (c_implicite_revizuite).
      -- r5h (#825 r5g NO-GO, Jak P1): și spre MUTATORII de cale (c_mut), ca spre închidere: un trigger INVOKER care face
      -- set_config('search_path', 'storage, public', true) pe un tabel auxiliar, pornit de un DEFINER cu cale fixă care inserează
      -- acolo și apoi cheamă necalificat un cititor de platformă, schimbă calea efectivă FĂRĂ ca DEFINER-ul să numească mutatorul
      -- (deci el nu devine mutator, iar apelul necalificat se judecă pe calea declarată). Refuz explicit, cu obiectul numit; pe
      -- prod: 12 obiecte peste mutatori (11 trigger-e + issue_graphql_placeholder; tr_check_filters / issue_pg_net_access și în
      -- închidere), toate pe lista revizuită, cu corpul în amprentă
      FOR k_s IN SELECT x.d FROM (
          SELECT DISTINCT format('%s → %s%s', pg_describe_object(d.classid, d.objid, d.objsubid), d.refobjid::regprocedure,
                                 CASE WHEN d.refobjid = ANY (c_fn) THEN ' (obiect din catalog care cheamă o funcție din închiderea citirilor)'
                                      ELSE ' (obiect din catalog care cheamă un mutator de cale)' END) d
            FROM pg_depend d JOIN pg_proc q ON q.oid = d.refobjid JOIN pg_language l ON l.oid = q.prolang
                 CROSS JOIN LATERAL pg_identify_object(d.classid, d.objid, d.objsubid) o
                 CROSS JOIN LATERAL pg_identify_object('pg_proc'::regclass, q.oid, 0) f
           WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = ANY (c_fn || c_mut)
             AND d.classid NOT IN ('pg_rewrite'::regclass, 'pg_proc'::regclass, 'pg_operator'::regclass, 'pg_cast'::regclass)
             AND format('%s %s=%s', o.type, o.identity, md5(concat_ws('|', o.type, o.identity, f.identity, pg_get_userbyid(q.proowner), q.prosecdef::text, coalesce(q.proconfig::text, ''), l.lanname, md5(q.prosrc || '|' || coalesce(q.prosqlbody::text, ''))))) <> ALL (c_implicite_revizuite)) x
        ORDER BY x.d COLLATE "C"
      LOOP
        v := array_append(v, 'invocare implicită neanalizată: ' || k_s || ' (citire nerevizuită)');
      END LOOP;
      IF EXISTS (SELECT 1 FROM pg_class vw WHERE vw.oid = ANY (c_rel)   -- alias ≠ variabila v
                  AND (vw.relkind = 'm' OR (vw.relkind = 'v' AND NOT coalesce(vw.reloptions && ARRAY['security_invoker=true','security_invoker=on','security_invoker=1'], false)))) THEN
        v := array_append(v, 'un view / view materializat citește registrul fără security_invoker (citire nerevizuită)');
      END IF;
      IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = ANY (c_fn) AND p.prosecdef) THEN
        v := array_append(v, 'o funcție DEFINER din afara registrului poate citi registrul — direct, prin view sau tranzitiv (citire nerevizuită)');
      END IF;
    END;
    -- writer-ul are exact ce-i trebuie (un GRANT retras ar lăsa activarea admisă și importul nefuncțional)
    -- câte un privilegiu pe rând: has_table_privilege(…, 'A,B') e adevărat dacă există ORICARE (Codex r4 8)
    IF EXISTS (SELECT 1 FROM (VALUES ('magazie_bucati','SELECT'), ('magazie_bucati','INSERT'), ('magazie_bucati','UPDATE'),
                                     ('magazie_bucati_evenimente','SELECT'), ('magazie_bucati_evenimente','INSERT'),
                                     ('magazie_bucati_miscari','SELECT'), ('magazie_bucati_miscari','INSERT'),
                                     ('izo_importuri','SELECT'), ('izo_importuri','INSERT'), ('izo_importuri','UPDATE'),
                                     ('izo_proiect_config','SELECT'), ('izo_proiect_config','INSERT'), ('izo_proiect_config','UPDATE'),
                                     ('izo_atribuiri','SELECT')) d(t, pr)
                WHERE NOT has_table_privilege('izo_registru_writer', 'public.' || d.t, d.pr))
       OR NOT (true
            AND has_sequence_privilege('izo_registru_writer', 'public.izo_server_ver_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.magazie_bucati_id_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.magazie_bucati_evenimente_id_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.magazie_bucati_miscari_id_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.izo_importuri_id_seq', 'USAGE')) THEN
      v := array_append(v, 'drepturile writer-ului (tabele / secvențe) incomplete');
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role']) a(n) WHERE has_table_privilege(a.n, 'public.magazie_bucati', 'TRUNCATE')) THEN
      v := array_append(v, 'TRUNCATE pe magazie_bucati pentru un rol API');
    END IF;
    -- definițiile (nu doar numele): amprenta curentă = cea fixată la migrare (review #806 r2)
    IF public.fn_izo_porti_definitii() IS DISTINCT FROM
       substring(obj_description('public.fn_izo_porti_definitii()'::regprocedure, 'pg_proc') FROM '^porti=([0-9a-f]{32})$') THEN
      v := array_append(v, 'definițiile porților diferă de amprenta de la migrare (trigger / politică / funcție / ACL modificat)');
    END IF;
    -- E3 (20261103b): poarta documentelor de intrare, chemată de aici, ca orice activare / import E2a s-o includă (r5d §13.1)
    v := v || public.fn_izo_porti_e3_lipsa();
    v := v || public.fn_izo_porti_e3b_lipsa();
    v := v || public.fn_izo_porti_e4_lipsa();
    RETURN v;
  END $f$;
  v_impl := (SELECT coalesce(array_agg(x.d ORDER BY x.d COLLATE "C"), '{}'::text[])
       FROM (SELECT DISTINCT format('%s|%s|%s', o.type, o.identity, f.identity) d
               FROM pg_depend d JOIN pg_proc q ON q.oid = d.refobjid
                    CROSS JOIN LATERAL pg_identify_object(d.classid, d.objid, d.objsubid) o
                    CROSS JOIN LATERAL pg_identify_object('pg_proc'::regclass, q.oid, 0) f
              WHERE d.refclassid = 'pg_proc'::regclass AND q.pronamespace = 'public'::regnamespace AND q.proname LIKE 'fn\_izo\_%'
                AND d.classid NOT IN ('pg_rewrite'::regclass, 'pg_proc'::regclass)) x);
